package it.unimi.dsi.fastutil.ints;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.stream.IntStream;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(java.util.concurrent.TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class IntOpenHashSetBenchmark {

    private IntOpenHashSet set;
    private List<Integer> initialElements;
    private final Random random = new Random(42);

    @Setup
    public void setup() {
        // 1. Create a list of 100 unique, non-trivial integers to populate the set.
        initialElements = new ArrayList<>(100);
        for (int i = 0; i < 100; i++) {
            initialElements.add(random.nextInt(100000)); // Generate random integers
        }

        // 2. Initialize the set by copying the list.
        set = new IntOpenHashSet(initialElements);
    }

    @Benchmark
    public Object measureAdd(Blackhole bh) {
        // Input generated based on state/setup context (randomly generated, but not constant)
        int newElement = random.nextInt(1000000);
        set.add(newElement);
        bh.consume(newElement);
        return null;
    }

    @Benchmark
    public Object measureContains(Blackhole bh) {
        // Pick an element known to be in the set (e.g., the first element added during setup)
        int existingElement = initialElements.get(0);
        boolean result = set.contains(existingElement);
        bh.consume(result);
        return null;
    }

    @Benchmark
    public Object measureRemove(Blackhole bh) {
        // Attempt to remove the first element added during setup
        int elementToRemove = initialElements.get(0);
        boolean removed = set.remove(elementToRemove);
        bh.consume(removed);
        return null;
    }

    @Benchmark
    public Object measureSize(Blackhole bh) {
        int size = set.size();
        bh.consume(size);
        return null;
    }

    @Benchmark
    public Object measureClear(Blackhole bh) {
        set.clear();
        bh.consume(null);
        return null;
    }

    @Benchmark
    public Object measureClone(Blackhole bh) {
        IntOpenHashSet clonedSet = set.clone();
        bh.consume(clonedSet);
        return null;
    }
}

