        final int size = 10000;
        initialElements = new int[size];
        for (int i = 0; i < size; i++) {
            initialElements[i] = rand.nextInt(size * 2); // Generate integers up to 20000
        }

        // 2. Build the set
        set = new IntRBTreeSet();
        for (int element : initialElements) {
