    public void measureSize(Blackhole bh) {
        // Test size()
        int size = set.size();
        bh.consume(size);
    }

    @Benchmark
    public void measureIteration(Blackhole bh) {
        // Test iterator operation (nextInt)
        if (set.size() > 0) {
            int value = set.iterator().nextInt();
            bh.consume(value);
        }
    }
}

