    private List<Integer> initialData;
    private final Random random = new Random();

    @Setup
    public void setup() {
        // Build a reasonably sized, non-trivial set of initial data
        initialData = new ArrayList<>(1000);
        for (int i = 0; i < 1000; i++) {
            initialData.add(random.nextInt(100000));
        }

        // Initialize the set using the array constructor for efficiency
        set = new IntRBTreeSet(initialData.stream().mapToInt(i -> i).toArray());
    }

    @Benchmark
    public void benchmarkAdd(Blackhole bh) {
        int value = random.nextInt(1000000);
        set.add(value);
        bh.consume(set);
    }

    @Benchmark
    public void benchmarkContains(Blackhole bh) {
        int value = random.nextInt(1000000);
        bh.consume(set.contains(value));
    }

    @Benchmark
    public void benchmarkRemove(Blackhole bh) {
        // Attempt to remove a value that is likely present (picking from the initial data range)
        int valueToRemove = initialData.get(random.nextInt(initialData.size()));
        bh.consume(set.remove(valueToRemove));
    }

