    public void benchmarkSize(Blackhole bh) {
        bh.consume(set.size());
    }

    @Benchmark
    public void benchmarkFirstInt(Blackhole bh) {
        bh.consume(set.firstInt());
    }

    @Benchmark
    public void benchmarkLastInt(Blackhole bh) {
        bh.consume(set.lastInt());
    }
}

