package it.unimi.dsi.fastutil.longs;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.function.LongConsumer;
import java.util.function.LongPredicate;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class LongArrayListBenchmark {

    private LongArrayList list;
    private long[] initialData;
    private final Random random = new Random(42);
    private static final int INITIAL_SIZE = 10000;

    @Setup
    public void setup() {
        // Initialize a large list with random data
        list = new LongArrayList();
        initialData = new long[INITIAL_SIZE];
        for (int i = 0; i < INITIAL_SIZE; i++) {
            initialData[i] = random.nextLong();
        }

        // Populate the list using the array constructor for a controlled initial state
        list = new LongArrayList(initialData);
    }

    @Benchmark
    public void measureAdd(Blackhole bh) {
        long value = random.nextLong();
        list.add(value);
        bh.consume(list);
    }

    @Benchmark
    public long measureGetLong(Blackhole bh) {
        int index = random.nextInt(list.size());
        long result = list.getLong(index);
        bh.consume(result);
        return result;
    }

    @Benchmark
    public void measureSet(Blackhole bh) {
        int index = random.nextInt(list.size());
        long newValue = random.nextLong();
        long oldValue = list.set(index, newValue);
        bh.consume(oldValue);
        bh.consume(list);
    }

    @Benchmark
    public void measureRemoveLong(Blackhole bh) {
        int indexToRemove = random.nextInt(list.size());
        long removedValue = list.removeLong(indexToRemove);
        bh.consume(removedValue);
        bh.consume(list);
    }

    @Benchmark
    public void measureClear(Blackhole bh) {
        list.clear();
        bh.consume(list);
    }

    @Benchmark
    public void measureForEach(Blackhole bh) {
        list.forEach(value -> {
            // Simple operation to ensure the lambda is executed
            bh.consume(value);
        });
    }

    @Benchmark
    public void measureTrim(Blackhole bh) {
        // Test trimming to half the current size
        int trimSize = list.size() / 2;
        list.trim(trimSize);
        bh.consume(list);
    }

    @Benchmark
    public void measureAddAll(Blackhole bh) {
        // Create a temporary source list
        List<Long> sourceList = new ArrayList<>(1000);
        for (int i = 0; i < 1000; i++) {
            sourceList.add(random.nextLong());
        }

        // Add the source list to the main list starting at index 0
        list.addAll(0, sourceList);
        bh.consume(list);
    }

    @Benchmark
    public void measureRemoveIf(Blackhole bh) {
        // Predicate: Remove all even numbers
        LongPredicate evenFilter = value -> value % 2 == 0;
        boolean modified = list.removeIf(evenFilter);
        bh.consume(modified);
        bh.consume(list);
    }
}

