package it.unimi.dsi.fastutil.objects;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.function.Predicate;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(java.util.concurrent.TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ObjectArrayListBenchmark {

    private ObjectArrayList<Integer> list;
    private final int INITIAL_SIZE = 1000;
    private final Integer[] initialData;
    private final Collection<Integer> removalCandidates;
    private final Predicate<Integer> removalFilter;

    @Setup
    public void setup() {
        // 1. Initialize data
        initialData = new Integer[INITIAL_SIZE];
        for (int i = 0; i < INITIAL_SIZE; i++) {
            initialData[i] = i;
        }

        // 2. Build the initial list using an array constructor
        list = ObjectArrayList.of(initialData);

        // 3. Prepare inputs for mutation benchmarks
        // Collection for addAll
        removalCandidates = new ArrayList<>(INITIAL_SIZE / 2);
        for (int i = 0; i < INITIAL_SIZE / 2; i++) {
            removalCandidates.add(i);
        }

        // Predicate for removeIf (e.g., remove even numbers)
        removalFilter = n -> n % 2 == 0;
    }

    @Benchmark
    public void measureAdd(Blackhole bh) {
        // Benchmark adding an element to the end
        list.add(9999);
        bh.consume(list);
    }

    @Benchmark
    public Integer measureGet(Blackhole bh) {
        // Benchmark reading an element from the middle
        Integer result = list.get(INITIAL_SIZE / 2);
        bh.consume(result);
        return result;
    }

    @Benchmark
    public Integer measureSet(Blackhole bh) {
        // Benchmark setting an element
        Integer old = list.set(100, 500);
        bh.consume(old);
        return old;
    }

    @Benchmark
    public Integer measureRemove(Blackhole bh) {
        // Benchmark removing an element by index
        Integer removed = list.remove(0);
        bh.consume(removed);
        return removed;
    }

    @Benchmark
    public Integer measureSize(Blackhole bh) {
        // Benchmark reading size
        Integer sizeResult = list.size();
        bh.consume(sizeResult);
        return sizeResult;
    }

    @Benchmark
    public Boolean measureRemoveAll(Blackhole bh) {
        // Benchmark removing a collection of elements
        boolean removed = list.removeAll(removalCandidates);
        bh.consume(removed);
        return removed;
    }

    @Benchmark
    public Boolean measureRemoveIf(Blackhole bh) {
        // Benchmark removing elements matching a predicate
        boolean removed = list.removeIf(removalFilter);
        bh.consume(removed);
        return removed;
    }

    @Benchmark
    public Integer measureToArray(Blackhole bh) {
        // Benchmark converting the list to an array
        Integer[] result = list.toArray();
        bh.consume(result);
        return result[0]; // Consume the array result
    }
}

